UPDATE companies SET description='LaMar Plastics & Displays, Ltd. has operated from Freeport, New York since 1965. The family‑owned company began as a supplier to the plastic packaging and point‑of‑purchase display markets and has remained under family control throughout its history.

The facility houses ten automatic in‑line vacuum forming machines plus two sample machines, four 5‑by‑10‑foot CNC router tables with tool changers, two HAAS CNC milling machines for aluminum tooling, and a 6‑by‑10‑foot 400‑watt laser cutter. Additional capabilities include silk screening, RF sealing, heat bending, flat‑bed digital printing (added in 2020), edge banding, wood staining and painting, and an in‑house CAD department that produces 3‑D renderings and prototypes.

LaMar serves the cosmetic, liquor, retail, and electronics sectors, producing point‑of‑purchase displays, clamshell packaging, ESD and anti‑static trays, and blister trays. The company also works with smaller startup customers, offering design, prototyping, manufacturing, and shipping under one roof.

Management emphasizes a one‑stop‑shop model that combines design, prototyping, production, and logistics, with a focus on quick sample turnaround and a willingness to take on low‑volume orders. Continuous investment in equipment such as digital printing and laser cutting is cited as a way to stay ahead of market trends.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Vacuum forming (thermoforming)", "CNC routing", "Laser cutting", "CNC milling (aluminum tooling)", "Silk screening", "RF sealing", "Heat bending", "Flat-bed digital printing", "CAD/3D design and rendering", "Prototyping", "Assembly", "Contract packaging", "Edge banding", "Wood staining and painting", "Material cutting (woods, plastics, acrylics, composites)", "Laser engraving"], "industries": ["Cosmetic", "Liquor", "Retail", "Electronics (ESD/Anti-static)", "Point-of-purchase displays", "Packaging"], "materials": ["Polystyrene", "Anti-Stat/ESD plastics", "PETG", "RPET", "PVC", "Woods (plywood, melamine, natural woods)", "Melamine", "Sintra", "Acrylic", "MDF", "Recycled Styrene", "Foam"], "equipment": ["10 in-line automatic vacuum forming machines", "2 large vacuum forming sample machines", "Four 5'' x 10'' CNC router tables with tool changers", "Two HAAS CNC milling machines", "One 6'' x 10'' x 400W CNC laser cutting machine", "Automatic edge banding machines", "RF sealing machines", "Custom heat bending machine", "Flat bed digital printing machine (2020)"], "volume": "", "lead_time": "", "tolerances": "Laser cutting kerf: 0.002 in", "built_on": ["Ten automatic in\u2011line vacuum forming machines for high\u2011volume thermoforming", "In\u2011house CAD and 3\u2011D rendering department for rapid prototyping", "Flat\u2011bed digital printing directly on woods, plastics, acrylics, and PETG", "RF sealing of customer products inside clamshell packages", "Fast sample turnaround and willingness to serve startup\u2011size orders"], "facts_used": ["Founded 1965 -> /", "Family-owned -> /", "Headquarters Freeport, NY -> db", "10 vacuum forming machines -> /services", "4 CNC router tables -> /services", "2 HAAS milling machines -> /services", "1 6''x10'' 400W laser cutter -> /services", "Silk screening -> /services", "RF sealing -> /services", "Heat bending -> /services", "Flat bed digital printing (2020) -> /services", "CAD/3D rendering -> /services", "Industries: cosmetic, liquor, retail, electronics -> /", "Materials: polystyrene, PETG, PVC, acrylic, etc. -> /services", "Laser kerf 0.002 in -> /services", "One-stop-shop model -> /", "Fast sample turnaround -> /", "Serves startup customers -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Manufacturer of Custom Retail Displays & Packaging", "founded_year": "1965", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='lamar-plastics-displays-ltd' AND approved AND profile IS NULL;
UPDATE companies SET description='Lacerta Group, LLC is headquartered in Mansfield, Massachusetts, and has been operating since 1993. The company was founded by the Lotfi family in the Boston empowerment zone and became a portfolio company of SK Capital Partners in 2020, with the founding family remaining involved in strategy and operations.

The company produces thermoformed plastic packaging, primarily using PET, and offers both stock and custom solutions. Its fully integrated manufacturing platform includes in-house design, printing, and film-sealable packaging capabilities. Lacerta operates seven facilities across the United States: three in Mansfield, one in Attleboro, Massachusetts, one in Chatsworth, California, and one in Portage, Wisconsin. An on-site warehouse stocks hundreds of packaging items ready for immediate shipment.

Lacerta serves commercial food producers, supermarkets, and convenience-store chains, supplying packaging for prepared foods such as sandwiches, wraps, salads, snacks, and party trays. Its products are designed for grab-and-go retail environments and emphasize shelf-life extension and tamper-evident features.

The company states that its differentiation rests on sustainability and speed to market. Its ReCERTA™ material incorporates an average of at least 10% post-consumer recycled content across all PET products, with custom blends available. Lacerta maintains SQF certification in the Manufacturing of Food Packaging and highlights a commitment to circularity, life-cycle assessment, and brand messaging support for customers.', certifications=ARRAY['SQF certification in Manufacturing of Food Packaging']::text[], profile='{"capabilities": ["Thermoforming", "PET packaging production", "Sustainable packaging (PCR blends)", "In-house design and engineering", "Custom packaging development", "Stock packaging fulfillment", "Film-sealable packaging", "Tamper-evident packaging", "Printing and decoration", "Life cycle assessment", "Brand messaging and sustainability consulting"], "industries": ["Food packaging", "Commercial food production", "Supermarkets and grocery", "Convenience stores", "Prepared foods", "Grab-and-go retail", "Sandwich and wrap packaging", "Salad and snack packaging", "Party and catering trays"], "materials": ["PET", "Post-consumer recycled plastic (PCR)", "ReCERTA\u2122 sustainable material"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["SQF certification in Manufacturing of Food Packaging", "ReCERTA\u2122 material with average 10% PCR content", "Fully integrated manufacturing platform with in-house design and printing", "On-site warehouse with hundreds of stock packaging solutions ready to ship", "Speed-to-market partnership model for custom packaging development"], "facts_used": ["Founded 1993 -> db, /about-us", "Headquarters Mansfield, MA -> db, /about-us", "Seven US facilities (Mansfield x3, Attleboro, Chatsworth, Portage) -> /about-us", "Founded by Lotfi family -> /about-us", "SK Capital Partners portfolio since 2020 -> /about-us", "SQF certification in Manufacturing of Food Packaging -> /about-us", "ReCERTA material with 