UPDATE companies SET description='LadyBug Technologies, LLC was founded in 2004 in Santa Rosa, California, by microwave engineers Richard Hawkins and Jon Sigler. The company relocated to Boise, Idaho in 2021, doubling its facility space and expanding manufacturing capacity by 30 percent. Hawkins serves as president, bringing four decades of RF and microwave test and measurement experience, while Sigler, a retired vice president and U.S. Marine veteran, contributed software and firmware expertise.

The company designs, develops, and manufactures a broad line of USB power sensors that function as complete, self-contained power measurement solutions without a separate meter. Covering 4 kHz to 67 GHz with 86 dB dynamic range, the product portfolio includes true RMS, peak/pulse/average, pulse profiling, and small form factor sensors, as well as the LB5900 series with optional I2C/SPI interfaces and Linux compatibility. LadyBug also provides NIST-traceable calibration services and power sensor rentals.

LadyBug’s sensors serve the microwave and RF test industry, automated test equipment (ATE) systems, defense applications, and portable or compact test setups. Customers use them for general-purpose RF power testing, military radar, and programmatic test environments such as LabVIEW and VEE.

The founders started the company to build a better product at a better price in the United States. LadyBug differentiates itself with patented NoZero NoCal technology that eliminates user zeroing and reduces drift, and with an integrated sensor architecture that removes the uncertainty of a separate meter. All analog and digitization circuitry is calibrated as a single unit under an ISO 9001:2015 quality system.', certifications=ARRAY['ISO 9001:2015','RoHS (RoHS-3)','REACH']::text[], profile='{"capabilities": ["USB power sensor design and manufacturing", "NIST-traceable calibration", "Power sensor rental", "Calibration and repair services", "RF and microwave test instrumentation development", "True RMS power measurement", "Peak, pulse, and average power measurement", "Pulse profiling", "Small form factor sensor production", "LAN-compatible sensor integration", "I2C/SPI interface implementation", "Linux-compatible firmware development"], "industries": ["Microwave and RF test and measurement", "Automated test equipment (ATE)", "Defense and military", "Portable and compact test applications", "General-purpose RF power testing"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Patented NoZero NoCal technology eliminates zeroing before measurement", "Self-contained USB power sensors replace separate power meter and sensor", "NIST-traceable calibration covering all analog and digitization circuitry", "Thermally stabilized design eliminates drift in test systems", "Frequency coverage from 4 kHz to 67 GHz with 86 dB dynamic range"], "facts_used": ["Founded in Santa Rosa, CA in 2004 -> /about-us", "Based in Boise, ID -> /about-us", "Founders: Richard Hawkins and Jon Sigler -> /about-us", "Designs, develops, manufactures USB power sensors -> /", "Frequency range 4 kHz to 67 GHz, 86 dB dynamic range -> /", "Patented NoZero NoCal feature -> /", "ISO 9001:2015 certified -> /quality", "RoHS compliance -> /quality", "REACH compliance -> /quality", "Moved to Boise in 2021, doubled space, added 30% manufacturing capacity -> /about-us", "Products: True RMS, Peak/Pulse/Average, Pulse Profiling, Small Form Factor, LAN Compatible -> /", "Industries: microwave and RF test, ATE, defense, portable -> /", "Calibration services -> /", "CAGE code registration -> /quality", "Human Rights Policy, Diversity, Safety -> /about-us", "LinkedIn URL -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "LadyBug Technologies designs, develops, and manufactures a broad range of first tier NIST traceable USB power sensors.", "founded_year": "2004", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/ladybug-technologies-llc/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ladybug-technologies-llc' AND approved AND profile IS NULL;
