='lincoln-plastics' AND approved AND profile IS NULL;
UPDATE companies SET description='Little Homestead Furniture was founded in 1987 in Rockville, Maryland, by a local architect who opened a showroom dedicated to solid American hardwood furniture. The store carries a range of solid hardwood furniture for every room, including bedroom sets, dining tables, sofas, and home office pieces. Its inventory is sourced from a network of small, family-owned factories in New England—particularly Vermont—as well as manufacturing partners in Pennsylvania, Ohio, Indiana, Texas, North Carolina, and Virginia. A made-to-order program allows customers to modify dimensions, finishes, and features, often at little or no extra cost. Little Homestead primarily serves residential customers in the Washington, D.C. metropolitan area who favor classic, timeless designs such as Shaker, Mission, Arts & Crafts, and contemporary styles. Buyers seek responsibly harvested hardwoods, dovetailed drawers, mortise-and-tenon joinery, and durable environmentally friendly finishes. The founder established the store as an alternative to mass-market furniture that often features distressed or weathered finishes and outsourced production. The emphasis is on well-crafted, real wood furniture made by American wood artisans, offered at reasonable prices with the flexibility of custom modifications.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Retail sales of solid hardwood furniture", "Made-to-order customization (dimensions, finishes, features)", "Showroom consultation", "Delivery"], "industries": ["Residential furniture retail"], "materials": ["Cherry", "Maple", "Oak", "Walnut", "Solid hardwoods"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Made-to-order modifications at minimal extra cost", "Solid hardwood construction with dovetailed drawers and mortise-and-tenon joinery", "Environmentally friendly finishes", "Showroom in Rockville, MD for in-person evaluation", "Sourced from family-owned factories in New England and partners across the U.S."], "facts_used": ["Founded in 1987 -> db", "Headquarters in Rockville, Maryland -> db", "Founded by a local architect nearly 40 years ago -> /about-us", "Offers solid American hardwood furniture for bedroom, dining, living room, home office, TV/media, youth bedrooms -> /about-us", "Sources from family-owned factories in New England (Vermont) and manufacturing partners in Pennsylvania, Ohio, Indiana, Texas, North Carolina, Virginia -> /about-us", "Made-to-order modifications possible at minimal extra cost -> /about-us", "Caters to DC area customers preferring classic, timeless designs -> /about-us", "Emphasizes responsibly harvested hardwoods, dovetailed drawers, mortise-and-tenon joinery, environmentally friendly finishes -> /about-us", "Showroom in Rockville, Maryland -> /about-us", "Materials: Cherry, Maple, Oak, Walnut -> /about-us"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "Little Homestead is a unique furniture store founded by a local architect nearly 40 years ago offering high quality North American furniture for the Bedroom, Dining Room, Living Room, Home Office, TV/Media, Youth Bedrooms, and more.", "founded_year": "1987", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='little-homestead-furniture' AND approved AND profile IS NULL;
UPDATE companies SET description='Loftis Steel & Aluminum, Inc. was founded in 2000 as a family-owned business in Nashville, Tennessee. The company began as a metals distributor and has grown into a regional supplier with a partnership with Tennessee Die Supply, operating from its Nashville facility to serve the Southeast.

