r", "makes_products": "yes", "type_evidence": "Each project is meticulously designed and manufactured in Largo, FL, USA.", "founded_year": "1999", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='mgi-apparel-solution-b2b-apparel-manufacture-seamless-cut-and-sew-socks-contract-embroidery' AND approved AND profile IS NULL;
UPDATE companies SET description='MJ Motorsports operates from Waipahu, Hawaii, as a retail destination for aftermarket automotive accessories. The shop specializes in parts and upgrades for Toyota trucks and SUVs, including the Tacoma, 4Runner, and Tundra. The business presents itself as a one-stop shop for owners looking to modify their vehicles for off-road use, camping, or daily driving.

